    left, right = 0, len(arr) - 1

    while left < right:
        mid = (left + right) // 2

        # If the middle element is the unique one
        if (mid % 2 == 0 and arr[mid] != arr[mid + 1]) or (mid % 2 == 1 and arr[mid] != arr[mid - 1]):
