def is_Sum_Of_Powers_Of_Two(n):
    if n <= 0:
        return False

    # Iterate over all bits in the binary representation of n
    while n > 0:
        # Check if the last bit is set (i.e., the number is odd)
        if n & 1:
            # If the number is odd, and we have more than one bit set
            # then it's not a sum of non-zero powers of 2
            if n != 1:
                n = n & (n - 1)  # Unset the last bit
            else:
                return True
        else:
            n >>= 1  # Shift right to check the next bit
    return False

