def even_binomial_Coeff_Sum(n):
    def binomial_coefficient(k, n):
        if k == 0 or k == n:
            return 1
        if k > n:
            return 0
        return binomial_coefficient(k-1, n-1) + binomial_coefficient(k, n-1)

    sum_even_index = 0
    for i in range(0, n+1, 2):
        sum_even_index += binomial_coefficient(i, n)
    return sum_even_index

